from gklib import L, S, Q
L("body","your-amazing-heart","8-10","Your Amazing Heart","How the heart pumps blood all around the body, every second of your life.","🫀",[
 S("A pump that never rests","Your heart is a muscle about the size of your fist. | It pumps blood around your body, beat after beat, day and night. | A child's heart beats roughly 70 to 100 times every minute when resting.",["A muscle the size of a fist","Pumps blood around the body","About 70 to 100 beats a minute"],"heartbeat"),
 S("Two loops","The blood goes around in two loops. | One loop carries blood to the lungs to pick up oxygen. | The other loop carries that fresh blood to all parts of the body, and brings the used blood back.",["Loop 1: heart to lungs","Loop 2: heart to body"],"heartbeat"),
 S("Four rooms","The heart has four rooms called chambers. | The two upper chambers are the atria and the two lower ones are the ventricles. | Little doors called valves make sure the blood only flows one way, and the 'lub-dub' sound you hear is those valves closing.",["Two atria on top","Two ventricles below","Valves keep blood one way"],"heartbeat"),
 S("Look after it","You can feel your pulse on your wrist, it is the blood pushing through with each heartbeat. | Running makes your heart beat faster because your muscles need more oxygen. | Playing, eating fruit and vegetables and sleeping well all help keep your heart strong.",["Pulse = the push of each beat","Exercise makes it stronger"]),
],facts=["Your heart beats more than 100,000 times a day.","If all the blood vessels in an adult were laid end to end, they would stretch about 100,000 kilometres.","The blue whale has the biggest heart of any animal: one that was weighed came to about 180 kilograms."],
quiz=[Q("How many chambers does the human heart have?",["Two","Three","Four"],2,"Two atria and two ventricles make four chambers."),
Q("What do the valves of the heart do?",["Make blood red","Keep blood flowing one way","Make the heart beat"],1,"Valves are one-way doors for blood."),
Q("Why does your heart beat faster when you run?",["It is bored","Muscles need more oxygen","It is cold"],1,"Working muscles need more oxygen, so the heart pumps faster to deliver it.")],tags=["heart","blood","circulation"],notes="Resting heart rate ranges are typical values and vary between children.")

L("body","how-your-brain-works","11-13","How Your Brain Works","Neurons, memory and why sleep matters: a tour of the control centre of your body.","🧠",[
 S("The control centre","Your brain is the control centre of your body. | It weighs about 1.4 kilograms and is made of around 86 billion tiny cells called neurons. | Neurons talk to each other with tiny electric signals and chemical messages.",["About 86 billion neurons","Electric and chemical signals"]),
 S("Parts and jobs","The big wrinkled top part is the cerebrum, which handles thinking, speaking and planning. | The cerebellum at the back helps with balance and movement. | The brain stem connects to the spinal cord and controls things you do without thinking, such as breathing.",["Cerebrum: thinking","Cerebellum: balance","Brain stem: breathing"]),
 S("Learning changes the brain","When you practise something, the neurons you use form stronger connections. | That is why practice makes a skill easier, whether it is riding a bicycle or solving a sum. | The brain keeps this ability to change throughout life, which scientists call neuroplasticity.",["Practice strengthens connections","The brain keeps changing"]),
 S("Sleep and memory","While you sleep, your brain sorts what you learned during the day. | Without enough sleep it is harder to pay attention and to remember things. | Children between about 6 and 12 years usually need nine to twelve hours of sleep.",["Sleep helps memory","Children need 9 to 12 hours"]),
],facts=["The brain uses about one fifth of the body's energy, though it is only about two percent of its weight.","Information can travel along some neurons at more than 100 metres per second.","You do not use only ten percent of your brain: nearly all of it is active over a day."],
quiz=[Q("Which part helps with balance?",["Cerebrum","Cerebellum","Brain stem"],1,"The cerebellum coordinates balance and movement."),
Q("Why does practice help you improve?",["It makes the head bigger","It strengthens connections between neurons","It stops sleep"],1,"Repeating something strengthens the pathways used."),
Q("About how much sleep do children aged 6 to 12 usually need?",["4 to 5 hours","9 to 12 hours","15 hours"],1,"Most children in this age group need 9 to 12 hours.")],tags=["brain","neurons","sleep"])

L("body","five-senses-and-more","5-7","Your Five Senses","See, hear, smell, taste and touch: how your body tells you about the world.","👀",[
 S("Five helpers","You have five senses: sight, hearing, smell, taste and touch. | Each sense has its own body part: eyes, ears, nose, tongue and skin. | They send messages to your brain, and your brain tells you what is happening.",["Eyes, ears, nose, tongue, skin","Messages go to the brain"]),
 S("Seeing and hearing","Your eyes catch light and your brain turns it into pictures. | Your ears catch sound waves, tiny shakes in the air, and your brain turns them into sounds. | Never poke anything into your ears or eyes, and keep loud sounds away from your ears.",["Eyes catch light","Ears catch sound"]),
 S("Smell and taste","Your nose can tell many different smells. | Your tongue can tell sweet, salty, sour, bitter and savoury tastes. | Smell and taste work together, and that is why food seems to have no taste when your nose is blocked.",["Nose smells","Tongue tastes","They work together"]),
 S("Touch","Your skin can feel hot, cold, soft, rough, and pain. | It feels pain to warn you when something might hurt you. | The skin is the largest organ of your body.",["Skin feels many things","Pain is a warning"]),
],facts=["Fingertips are one of the most sensitive parts of the body.","A dog's sense of smell is far stronger than ours.","Your tongue has thousands of tiny taste buds."],
quiz=[Q("Which part helps you smell?",["Nose","Ear","Hand"],0,"The nose senses smells."),
Q("Which sense do you use to feel something soft?",["Sight","Hearing","Touch"],2,"Skin feels touch."),
Q("How many senses do we usually talk about?",["Three","Five","Ten"],1,"Sight, hearing, smell, taste and touch.")],tags=["senses","body"])

L("nature","food-chains-who-eats-whom","8-10","Food Chains: Who Eats Whom?","Energy starts with the Sun and passes along a chain of plants and animals.","🦊",[
 S("Plants make food","Almost every food chain starts with a plant. | Plants use sunlight, water and air to make their own food, so we call them producers. | The Sun is the original source of the energy.",["Plants are producers","Energy comes from the Sun"],"food-chain"),
 S("Eaters","Animals cannot make their own food, so they are called consumers. | Herbivores eat plants, carnivores eat other animals, and omnivores eat both. | A grasshopper eats grass, a frog eats the grasshopper, and a snake eats the frog.",["Herbivores eat plants","Carnivores eat animals","Omnivores eat both"],"food-chain"),
 S("Cleaning up","When plants and animals die, tiny living things called decomposers, such as fungi and bacteria, break them down. | This returns nutrients to the soil, which helps new plants grow. | The cycle then continues.",["Decomposers break down the dead","Nutrients return to the soil"],"food-chain"),
 S("Webs and balance","In real life animals eat many things, so food chains join up into a food web. | If one kind of animal disappears, others in the web are affected. | That is why protecting nature, even small insects, matters.",["Chains join into webs","Every link matters"]),
],facts=["Only about ten percent of the energy at one level of a food chain reaches the next level.","A single tiger needs a large forest because it sits near the top of a long food chain.","Mushrooms are not plants: fungi form their own kingdom of life."],
quiz=[Q("What do we call plants in a food chain?",["Consumers","Producers","Decomposers"],1,"Plants make food from sunlight, so they are producers."),
Q("An animal that eats only plants is a...",["Carnivore","Herbivore","Omnivore"],1,"Herbivores eat plants."),
Q("What do decomposers do?",["Make sunlight","Break down dead things","Hunt animals"],1,"Fungi and bacteria break down dead plants and animals and return nutrients to the soil.")],tags=["food chain","ecosystem"])

L("nature","how-plants-make-food","8-10","How Plants Make Food","Photosynthesis explained simply: sunlight, water and air become food and fresh oxygen.","🌿",[
 S("What plants need","Plants need three main things to make food: sunlight, water and carbon dioxide from the air. | Roots take in water from the soil. | Tiny holes in the leaves called stomata let air in and out.",["Sunlight, water, carbon dioxide","Roots drink water","Leaves breathe through stomata"],"photosynthesis"),
 S("The green kitchen","Leaves have a green substance called chlorophyll. | It catches energy from sunlight. | Using that energy, the plant turns water and carbon dioxide into a sugar called glucose, and this process is photosynthesis.",["Chlorophyll catches light","Makes sugar called glucose"],"photosynthesis"),
 S("A gift of oxygen","While making food, the plant gives out oxygen. | Animals and people breathe in that oxygen. | We breathe out carbon dioxide, which the plants can use again, so plants and animals help each other.",["Plants release oxygen","We release carbon dioxide"],"photosynthesis"),
 S("Where it goes","The sugar is used for growing, and the extra is stored as starch in roots, seeds and fruits. | That stored food is what we eat when we eat potatoes, rice or apples. | Without photosynthesis there would be almost no food or oxygen for living things.",["Sugar helps the plant grow","Extra is stored as starch"]),
],facts=["The oceans' tiny floating plants, called phytoplankton, make about half of the oxygen on Earth.","Leaves look green because chlorophyll reflects green light.","In autumn some leaves turn red or yellow when the green chlorophyll fades."],
quiz=[Q("Which gas do plants take in for photosynthesis?",["Oxygen","Carbon dioxide","Nitrogen"],1,"Plants use carbon dioxide from the air."),
Q("What does chlorophyll do?",["Catches sunlight energy","Takes up water","Makes seeds"],0,"Chlorophyll absorbs light energy so the leaf can make food."),
Q("What gas do plants give out?",["Oxygen","Smoke","Carbon dioxide only"],0,"Photosynthesis releases oxygen.")],tags=["plants","photosynthesis"])

L("nature","amazing-animal-abilities","5-7","Amazing Animal Abilities","Meet animals with super senses, strange homes and clever tricks.","🐘",[
 S("Super senses","Bats find their way in the dark by making high sounds and listening for the echoes. | Eagles can spot a tiny animal from very far away. | Dogs can smell things that people cannot notice at all.",["Bats use echoes","Eagles see far","Dogs smell very well"]),
 S("Clever builders","Weaver birds build hanging nests by knotting grass. | Honey bees make neat six-sided honeycomb to store honey. | Termites build tall mud towers that stay cool inside.",["Weaver birds knot nests","Bees build honeycomb"]),
 S("Staying safe","A chameleon can change colour to blend into its surroundings. | A porcupine has sharp quills to keep enemies away. | Some animals, like the elephant, live in big family groups that protect each other.",["Chameleon hides by colour","Quills give protection"]),
 S("Giants and tiny ones","The blue whale is the biggest animal that has ever lived. | Elephants are the biggest land animals. | The tiniest animals, like some ants and beetles, are smaller than a grain of rice.",["Blue whale: biggest animal","Elephant: biggest on land"]),
],facts=["An elephant's trunk has tens of thousands of muscles and can pick up a coin.","A hummingbird can flap its wings dozens of times every second.","An octopus has three hearts."],
quiz=[Q("How do bats find their way in the dark?",["Echoes","Magic","Bright eyes"],0,"Bats make sounds and listen for the echoes that bounce back."),
Q("Which is the biggest land animal?",["Giraffe","Elephant","Horse"],1,"The elephant is the biggest land animal."),
Q("Which animal can change colour to hide?",["Chameleon","Sparrow","Cow"],0,"Chameleons change colour.")],tags=["animals","fun"])
